function UICultivateCareerTypeNode:RefreshUI(occupationId)
    occupationId = checkNumber(occupationId)
    self.occupationId = occupationId
    local isShow = checkNumber(occupationId) > 0
    KTool.SetActive(self.controller.gameObject, isShow)
    if isShow then
        local jobVo = cardConfMgr:GetCardCareerRowByType(occupationId)
        local icon = jobVo.icon
        CfUtils.FillImage(self.TypeIcon.gameObject, icon)
    end
end

